        {
          "type": "aggregate",
          "groupby": [
            "m"
          ],
          "ops": [
            "sum",
            "sum"
          ],
          "fields": [
            "gb",
            "ec"
          ],
          "as": [
            "gb",
            "ec"
          ]
        },
        {
          "type": "formula",
          "as": "teams",
          "expr": "datum.ec * rT"
        },
        {
          "type": "formula",
          "as": "mach",
          "expr": "datum.ec * rM"
        },
        {
          "type": "formula",
          "as": "net",
          "expr": "datum.gb - datum.ec"
        },
        {
          "type": "collect",
          "sort": {
            "field": "m"
          }
        }
      ]
    }
